        <div class="project-hero-facts"><div><?= listingIcon('building') ?><span>Developer</span><strong><?= e($value($project['developer_name']??'')) ?></strong></div><div><?= listingIcon('area') ?><span>Unit size</span><strong><?= e($area) ?></strong></div><div><?= listingIcon('house') ?><span>Total units</span><strong><?= e($value($project['total_units']??'')) ?></strong></div></div>
        <div class="project-summary-progress"><div><span><?= $sample?'Illustrative progress':'Development progress' ?></span><strong><?= $progress ?>%</strong></div><progress value="<?= $progress ?>" max="100" aria-label="Development progress"><?= $progress ?>%</progress></div>
        <div class="pd-overview-actions"><a class="button" href="#contact-project">Enquire about this project</a><a href="#project-pricing">View pricing plan &rarr;</a></div>
